// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/drift.ts`. Edit the source and run `just generate`.
// The drift check: the differences between the active settings and the settings snippet of the wiki, as lines for Claude.
// The functions are pure, so the lab test and the hooks module share them.

import type { ContextSkill, Settings } from "claude-code";
import type { RuleProblem } from "../../../kernel/rules.ts";
import { GAP_KEYS_MAX, RULE_LINES_MAX } from "../limits.ts";
import {
  DRIFT_NOTE,
  GAPS_VALUE_KEY,
  GAPS_VALUE_KEYS,
  GAPS_VALUES_KEY,
  GAPS_VALUES_KEYS,
  GUARD_SEATED,
  GUARD_SKIPS,
  IDLE_ENV_UNREAD,
  IDLE_ENV_WINDOW,
  OVERRIDE_ENV_MANY,
  OVERRIDE_ENV_ONE,
  PLUGINS_ON_MANY,
  PLUGINS_ON_ONE,
  RULE_BUDGET,
  RULE_GIT,
  RULE_GLOB,
  RULE_MORE_MANY,
  RULE_MORE_ONE,
  RULE_YAML,
  STALE_AGENT_SOCKET,
  STALE_STATUS_MANY,
  STALE_STATUS_ONE,
  SYNCED_SKILLS_MANY,
  SYNCED_SKILLS_ONE,
} from "../prompts.ts";
import { planAutoMode } from "./automode.ts";
import {
  COMPACT_OFF_ENV,
  OFF_PLUGINS,
  OVERRIDE_ENV,
  SYNCED_SOURCE,
  UNREAD_ENV,
  WINDOW_ENV,
} from "./facts.ts";
import {
  commandOf,
  isOurStatusLine,
  mergeSettings,
  snippetFor,
} from "./merge.ts";
import { staleAgentSockets } from "./sandbox.ts";
import type { Change } from "./types.ts";

const names = (list: string[]) => list.map((n) => `\`${n}\``).join(", ");

/** The status line commands of the snippet, which hold the plugin folder. */
const STATUS_KEYS = ["statusLine.command", "subagentStatusLine.command"];

/**
 * The key paths of the snippet that `settings` does not have or holds with another value.
 * `root` is the folder of the running plugin, so a status line command of another version is a gap.
 * The built-in plugins have their own line, so their keys are not here.
 * The `autoMode` lists are checked against `user` only, the user settings, because Claude Code reads them only from there.
 * `user` is undefined when the check of `autoMode` does not apply, so no `autoMode` gap is reported.
 */
export const snippetGaps = (
  settings: Settings,
  root: string,
  user?: Settings,
): string[] => {
  const changes: Change[] = [];
  const want = snippetFor(settings, root);
  mergeSettings(settings, want, "", changes);
  if (user) planAutoMode(user, changes);
  // The merged view can repeat or add models, so `availableModels` is a gap only when it lacks a model of the snippet.
  const have: unknown[] = Array.isArray(settings["availableModels"])
    ? settings["availableModels"]
    : [];
  const models = (want["availableModels"] ?? []) as string[];
  const allModels = models.every((m) => have.includes(m));
  return changes
    .map((c) => c.key)
    .filter((key) => !key.startsWith("enabledPlugins."))
    .filter((key) => !(key === "availableModels" && allModels));
};

/**
 * The status line commands of `settings` that run the status line of a claudetto folder other than `root`.
 */
export const staleStatusLines = (
  settings: Settings,
  root: string,
): string[] => {
  const want = snippetFor(settings, root);
  return STATUS_KEYS.filter((key) => {
    const [name = ""] = key.split(".");
    const command = commandOf(settings, name);
    return (
      typeof command === "string" &&
      isOurStatusLine(command) &&
      command !== commandOf(want, name)
    );
  });
};

/** True when the `env` value turns a flag on: it is set, and it is not `0` or `false`. */
const isOn = (value: unknown): boolean =>
  typeof value === "string" &&
  !["", "0", "false"].includes(value.toLowerCase());

/**
 * The lines for the `env` keys of `settings` that have no effect.
 * Claude Code never reads the names of `UNREAD_ENV`, and it reads `WINDOW_ENV` only with `COMPACT_OFF_ENV` on.
 */
export const idleEnvLines = (settings: Settings | undefined): string[] => {
  const env = (settings?.["env"] ?? {}) as Record<string, unknown>;
  const lines = Object.entries(UNREAD_ENV)
    .filter(([name]) => name in env)
    .map(([name, instead]) => IDLE_ENV_UNREAD({ name, instead }));
  if (WINDOW_ENV in env && !isOn(env[COMPACT_OFF_ENV]))
    lines.push(
      IDLE_ENV_WINDOW({ window: WINDOW_ENV, compactOff: COMPACT_OFF_ENV }),
    );
  return lines;
};

/**
 * The built-in plugins of the snippet that the settings do not turn off.
 */
export const pluginsOn = (settings: Settings | undefined) => {
  const enabled = settings?.["enabledPlugins"] as
    | Record<string, unknown>
    | undefined;
  return OFF_PLUGINS.filter((id) => enabled?.[id] !== false);
};

/**
 * The synced skills in the entries of the skill listing.
 */
export const syncedSkills = (skills: ContextSkill[] = []) =>
  skills.filter((s) => s.source === SYNCED_SOURCE).map((s) => s.name);

/**
 * Whether the guard is seated: managed settings exist when the policy source has a key.
 */
export const isSeated = (policy: Settings | undefined) =>
  Object.keys(policy ?? {}).length > 0;

/**
 * The lines for the rule problems, at most `RULE_LINES_MAX`, and one line for the rest.
 * The facts come from `checkRule` in the kernel: the caller reads the files, because this module has no I/O.
 */
export const ruleLines = (problems: readonly RuleProblem[]): string[] => {
  const lines = problems.map((p) => {
    if (p.kind === "yaml") return RULE_YAML({ rule: p.rule });
    if (p.kind === "git") return RULE_GIT({ rule: p.rule });
    if (p.kind === "budget")
      return RULE_BUDGET({ rule: p.rule, count: String(p.count) });
    return RULE_GLOB({ rule: p.rule, glob: p.glob ?? "" });
  });
  const more = lines.length - RULE_LINES_MAX;
  return more > 0
    ? [
        ...lines.slice(0, RULE_LINES_MAX),
        (more > 1 ? RULE_MORE_MANY : RULE_MORE_ONE)({ count: String(more) }),
      ]
    : lines;
};

/**
 * The lines of the drift check, in a fixed order.
 * The facts are `settings` (merged), `policy` (the managed source), `skills` (the listing entries),
 * and `blocking` (the value of each variable that overrides the agent files).
 * `user` is the user settings, which hold the `autoMode` lists that count.
 * `rules` are the problems of the rule files of the project.
 * A fact that the caller could not read is undefined, and it gives no line.
 * The result is empty when nothing differs.
 */
export const driftLines = ({
  settings,
  policy,
  skills,
  blocking = {},
  root,
  user,
  rules = [],
  agentSocket,
}: {
  settings?: Settings | undefined;
  policy?: Settings | undefined;
  skills?: ContextSkill[] | undefined;
  blocking?: Record<string, string | undefined>;
  /** The folder of the running plugin. */
  root?: string;
  /** The user settings. Claude Code reads the `autoMode` lists only from them. */
  user?: Settings | undefined;
  /** The problems of the rule files of the project, from `checkRule`. */
  rules?: readonly RuleProblem[];
  /** The value of `SSH_AUTH_SOCK`. */
  agentSocket?: string | undefined;
}): string[] => {
  const lines: string[] = [];
  if (isSeated(policy))
    lines.push(GUARD_SEATED({ skips: GUARD_SKIPS.join(" and ") }));
  const stale = settings && root ? staleStatusLines(settings, root) : [];
  if (stale.length)
    lines.push(
      (stale.length > 1 ? STALE_STATUS_MANY : STALE_STATUS_ONE)({
        names: names(stale),
        root: root ?? "",
      }),
    );
  const gaps =
    settings && root
      ? snippetGaps(settings, root, user).filter((k) => !stale.includes(k))
      : [];
  if (gaps.length) {
    const keys = [...new Set(gaps.map((k) => k.split(".")[0] ?? k))];
    const more = keys.length - GAP_KEYS_MAX;
    const gapText = gaps.length > 1 ? "values" : "value";
    const keyText = keys.length > 1 ? "keys" : "key";
    const text = {
      "value key": GAPS_VALUE_KEY,
      "value keys": GAPS_VALUE_KEYS,
      "values key": GAPS_VALUES_KEY,
      "values keys": GAPS_VALUES_KEYS,
    }[`${gapText} ${keyText}`] as typeof GAPS_VALUE_KEY;
    lines.push(
      text({
        count: String(gaps.length),
        keys: `${names(keys.slice(0, GAP_KEYS_MAX))}${more > 0 ? `, and ${more} more` : ""}`,
      }),
    );
  }
  const on = settings ? pluginsOn(settings) : [];
  if (on.length)
    lines.push(
      (on.length > 1 ? PLUGINS_ON_MANY : PLUGINS_ON_ONE)({ names: names(on) }),
    );
  const synced = syncedSkills(skills);
  if (synced.length)
    lines.push(
      (synced.length > 1 ? SYNCED_SKILLS_MANY : SYNCED_SKILLS_ONE)({
        count: String(synced.length),
      }),
    );
  const set = OVERRIDE_ENV.filter((k) => blocking[k]);
  if (set.length)
    lines.push(
      (set.length > 1 ? OVERRIDE_ENV_MANY : OVERRIDE_ENV_ONE)({
        names: names(set),
      }),
    );
  const sockets = settings ? staleAgentSockets(settings, agentSocket) : [];
  if (sockets.length)
    lines.push(STALE_AGENT_SOCKET({ folders: names(sockets) }));
  lines.push(...idleEnvLines(settings));
  lines.push(...ruleLines(rules));
  return lines;
};

/**
 * The text for the session, or undefined when no line exists.
 * The settings are the decision of the user, so the note gives each fix as a fact about the user.
 * In an eval run, Claude changed `/config/settings.json` from a line of this note (2026-10-09).
 */
export const driftNote = (lines: string[]) =>
  lines.length
    ? DRIFT_NOTE({ lines: lines.map((l) => `- ${l}`).join("\n") })
    : undefined;
